import { getChainAddresses, VaultMarketPublicAllocatorConfig, } from "@morpho-org/blue-sdk";
import { getChainId, readContract } from "viem/actions";
import { publicAllocatorAbi } from "../abis.js";
// biome-ignore lint/complexity/useMaxParams: TODO refactor to ≤2 params
export async function fetchVaultMarketPublicAllocatorConfig(vault, marketId, client, parameters = {}) {
    parameters.chainId ??= await getChainId(client);
    const { publicAllocator } = getChainAddresses(parameters.chainId);
    if (publicAllocator == null)
        return;
    const [maxIn, maxOut] = await readContract(client, {
        ...parameters,
        address: publicAllocator,
        abi: publicAllocatorAbi,
        functionName: "flowCaps",
        args: [vault, marketId],
    });
    return new VaultMarketPublicAllocatorConfig({
        vault,
        marketId,
        maxIn,
        maxOut,
    });
}
